sys_script_include.script:
var ClaudeRequestLogger = Class.create();
ClaudeRequestLogger.prototype = {
    initialize: function() {},

    /**
     * Create a pending staging record before the API call.
     * @param {Object} params - { session_id, model, prompt, system_prompt, max_tokens }
     * @returns {string} sys_id of the created record
     */
    createPending: function(params) {
        params = params || {};
        var gr = new GlideRecord('x_146833_claudec_0_request');
        gr.initialize();
        gr.setValue('session_id',         params.session_id   || '');
        gr.setValue('model',              params.model        || '');
        gr.setValue('status',             'pending');
        gr.setValue('prompt',             (params.prompt        || '').substring(0, 4000));
        gr.setValue('system_prompt',      (params.system_prompt || '').substring(0, 4000));
        gr.setValue('max_tokens_requested', params.max_tokens || 0);
        gr.setValue('input_tokens',       0);
        gr.setValue('output_tokens',      0);
        gr.setValue('tool_rounds',        0);
        gr.setValue('duration_ms',        0);
        // Capture current user
        try { gr.setValue('requested_by', gs.getUserID()); } catch(e) {}
        var sysId = gr.insert();
        return sysId ? sysId.toString() : '';
    },

    /**
     * Update a staging record after a successful API response.
     * @param {string} sysId  - sys_id from createPending
     * @param {Object} result - { text, model, inputTokens, outputTokens, toolRounds, durationMs }
     */
    markSuccess: function(sysId, result) {
        if (!sysId) { return; }
        result = result || {};
        var gr = new GlideRecord('x_146833_claudec_0_request');
        if (!gr.get(sysId)) { return; }
        gr.setValue('status',          'success');
        gr.setValue('model',           result.model        || gr.getValue('model'));
        gr.setValue('response_text',   (result.text || '').substring(0, 8000));
        gr.setValue('input_tokens',    result.inputTokens  || 0);
        gr.setValue('output_tokens',   result.outputTokens || 0);
        gr.setValue('tool_rounds',     result.toolRounds   || 0);
        gr.setValue('duration_ms',     result.durationMs   || 0);
        gr.update();
    },

    /**
     * Update a staging record after a failed API call.
     * @param {string} sysId     - sys_id from createPending
     * @param {string} errorMsg  - Error detail string
     * @param {number} durationMs
     */
    markError: function(sysId, errorMsg, durationMs) {
        if (!sysId) { return; }
        var gr = new GlideRecord('x_146833_claudec_0_request');
        if (!gr.get(sysId)) { return; }
        gr.setValue('status',        'error');
        gr.setValue('error_message', (errorMsg || '').substring(0, 1000));
        gr.setValue('duration_ms',   durationMs || 0);
        gr.update();
    },

    /**
     * Log an individual tool execution to x_146833_claudec_0_tool_log.
     * @param {Object} params - { request_id, round_number, tool_name, input_json, output_text, execution_ms, success }
     * @returns {string} sys_id of the created tool_log record
     */
    logToolExecution: function(params) {
        params = params || {};
        var gr = new GlideRecord('x_146833_claudec_0_tool_log');
        gr.initialize();
        if (params.request_id) {
            gr.setValue('request', params.request_id);
        }
        gr.setValue('round_number', params.round_number || 1);
        gr.setValue('tool_name',    params.tool_name || '');
        gr.setValue('input_json',   (typeof params.input_json === 'string' ? params.input_json : JSON.stringify(params.input_json || {})).substring(0, 4000));
        gr.setValue('output_text',  (params.output_text != null ? params.output_text + '' : '').substring(0, 4000));
        gr.setValue('execution_ms', params.execution_ms || 0);
        gr.setValue('success',      params.success !== false);
        var sysId = gr.insert();
        return sysId ? sysId.toString() : '';
    },

    /**
     * Return all logged requests for a given session as an array of plain objects.
     * @param {string} sessionId
     * @returns {Array}
     */
    getSessionHistory: function(sessionId) {
        if (!sessionId) { return []; }
        var records = [];
        var gr = new GlideRecord('x_146833_claudec_0_request');
        gr.addQuery('session_id', sessionId);
        gr.orderBy('sys_created_on');
        gr.query();
        while (gr.next()) {
            records.push({
                sys_id:               gr.getUniqueValue(),
                created_on:           gr.getValue('sys_created_on'),
                session_id:           gr.getValue('session_id'),
                model:                gr.getValue('model'),
                status:               gr.getValue('status'),
                prompt:               gr.getValue('prompt'),
                system_prompt:        gr.getValue('system_prompt'),
                response_text:        gr.getValue('response_text'),
                input_tokens:         parseInt(gr.getValue('input_tokens'),  10) || 0,
                output_tokens:        parseInt(gr.getValue('output_tokens'), 10) || 0,
                max_tokens_requested: parseInt(gr.getValue('max_tokens_requested'), 10) || 0,
                tool_rounds:          parseInt(gr.getValue('tool_rounds'),   10) || 0,
                duration_ms:          parseInt(gr.getValue('duration_ms'),   10) || 0,
                error_message:        gr.getValue('error_message') || ''
            });
        }
        return records;
    },

    type: 'ClaudeRequestLogger'
};
